questions.solution:
#include <iostream>
using namespace std;
long long power(long long b,int e){if(e==0)return 1;long long h=power(b,e/2);if(e%2==0)return h*h;return h*h*b;}
int main(){long long b;int e;cin>>b>>e;cout<<power(b,e);}

