questions.solution:
#include <iostream>
using namespace std;
void hanoi(int n,char from,char to,char via){if(n==0)return;hanoi(n-1,from,via,to);cout<<from<<"->"<<to<<"\n";hanoi(n-1,via,to,from);}
int main(){int n;cin>>n;hanoi(n,'A','C','B');}

