#include <iostream>
using namespace std;
int main(){int n,x,a[1000];cin>>n;for(int i=0;i<n;i++)cin>>a[i];cin>>x;int l=0,r=n-1,ans=-1;while(l<=r){int m=(l+r)/2;if(a[m]==x){ans=m;break;}else if(a[m]<x)l=m+1;else r=m-1;}cout<<ans;}
